import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String nStr = br.readLine();
        if (nStr == null || nStr.trim().isEmpty()) {
            return;
        }
        int n = Integer.parseInt(nStr.trim());
        if (n == 0) {
            System.out.println();
            return;
        }
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            System.out.println();
            return;
        }
        String[] parts = line.trim().split("\\s+");
        int bucketCount = n;
        List<Double>[] buckets = new ArrayList[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new ArrayList<>();
        }
        int idx = 0;
        for (int i = 0; i < n && idx < parts.length; i++) {
            String part = parts[idx++].trim();
            if (part.isEmpty()) continue;
            double num = Double.parseDouble(part);
            int bucketIndex = (int) (num * bucketCount);
            if (bucketIndex >= bucketCount) bucketIndex = bucketCount - 1;
            buckets[bucketIndex].add(num);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bucketCount; i++) {
            Collections.sort(buckets[i]);
            for (double val : buckets[i]) {
                if (sb.length() > 0) sb.append(' ');
                sb.append(String.format("%.2f", val));
            }
        }
        System.out.println(sb.toString());
    }
}
